-- GERADO por importers/run.py (restricoes_rmsp/ibge). Fonte: https://servicodados.ibge.gov.br/api/v3/malhas/estados/SP?formato=application/vnd.geo%2Bjson&qualidade=maxima&intrarregiao=municipio (39 municípios da RMSP, simplificado a ~10 m). Licença: IBGE — Malha Municipal (dados públicos, uso livre com citação da fonte: IBGE). Não edite à mão.
delete from data_features where layer_id = $q$restricoes_rmsp$q$ and source = $q$ibge$q$;
on conflict (layer_id, source, source_id) do nothing;
